 useEffect(()=>{const sync=()=>{const previous=current.current;positions.current[routeHash(previous)]=window.scrollY;let next=readCurrentPage(Object.keys(projects));if(next?.type==='article'&&previous?.type==='article'&&next.id===previous.id&&!next.returnTo&&previous.returnTo){next={...next,returnTo:previous.returnTo};history.replaceState({...history.state,makelog:{...history.state?.makelog,returnTo:next.returnTo}},'',location.href);}current.current=next;setModalState(next);};window.addEventListener('popstate',sync);window.addEventListener('hashchange',sync);return()=>{window.removeEventListener('popstate',sync);window.removeEventListener('hashchange',sync);};},[content]);
 useEffect(()=>{if(first.current){first.current=false;return;}const frame=requestAnimationFrame(()=>{window.scrollTo(0,modal?.restoreScroll??positions.current[routeHash(modal)]??0);if(!modal?.focusArticle)document.querySelector('main h1')?.focus({preventScroll:true});});return()=>cancelAnimationFrame(frame);},[modal?.type,modal?.id,modal?.project]);
