 {activeTab==='overview'&&<>{project.image&&<ProjectScreenshot project={project} lang={lang}/>}<div className="overview-copy"><h2 className="section-icon-title"><BookOpen size={22} aria-hidden="true"/>{builtIn?t('試せること','What you can try'):t('作品について','About this project')}</h2><p>{localized(project.description,lang)}</p><div className="case-actions"><ProjectDemoLink project={project} builtIn={builtIn} lang={lang} onOpen={()=>setModal({...modal,tab:'demo'})}/>{!builtIn&&project.repository&&<a className="text-link" href={repositoryUrl(project.repository)} target="_blank" rel="noopener noreferrer"><GithubLogo size={19} aria-hidden="true"/>{t('GitHubで見る','View on GitHub')}<Arrow diagonal/></a>}<ShareLink route={{...modal,tab:'overview'}} lang={lang}/></div></div>{builtIn&&<Repository project={modal.project} lang={lang}/>}{publicCommentsEnabled&&builtIn&&<CommunitySection project={modal.project} lang={lang} initialOpen={modal.tab==='comments'} comments={comments[modal.project]} onAdd={c=>setComments(v=>({...v,[modal.project]:[...v[modal.project],c]}))}/>}</>}
