function FormDemo({lang}){
 const t=useCopy(lang);const [rule,setRule]=useInteraction('form.rule','{date}_{title}'),[ran,setRan]=useInteraction('form.ran',false),[busy,setBusy]=useState(false);const timer=useRef();useEffect(()=>()=>clearTimeout(timer.current),[]);
 const docs=[{date:'2026-10-12',title:'sample-A'},{date:'2026-10-13',title:'sample-B'},{date:'2026-10-14',title:'sample-C'}];
 const valid=rule.trim().length>0&&rule.length<=70&&!/[\\/:*?"<>|]/.test(rule)&&/\{(date|title)\}/.test(rule)&&!/(\{[^}]*\})/.test(rule.replaceAll('{date}','').replaceAll('{title}',''));
 const filename=d=>`${rule.replaceAll('{date}',d.date).replaceAll('{title}',d.title).replace(/\.pdf$/i,'')}.pdf`;
 const run=()=>{setBusy(true);setRan(false);timer.current=setTimeout(()=>{setRan(true);setBusy(false);},600);};
 const download=()=>{const csv='\uFEFForiginal,renamed\n'+docs.map((d,n)=>[csvCell(`sample_0${n+1}.pdf`),csvCell(filename(d))].join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='makelog-demo-renames.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 return <div><div className="demo-intro"><p>{t('命名ルールを変えて、3つのサンプルで試せます。','Change the naming rule and try it on three sample documents.')}</p></div><div className="rename-workbench"><section><h4>{t('入力','Input')}</h4>{docs.map((d,n)=><div className="file-row" key={d.title}><FilePdf size={30} weight="light"/><div>sample_0{n+1}.pdf<small>{d.date} · {d.title}</small></div></div>)}</section><Arrow size={28}/><section aria-live="polite"><h4>{t('結果プレビュー','Result preview')}</h4>{docs.map(d=><div className={`file-row ${ran?'complete':''}`} key={d.title}><FilePdf size={30} weight="light"/><span>{busy?t('処理中…','Processing…'):ran?filename(d):t('実行後に表示','Run to preview')}</span>{ran&&<CheckCircle size={21} weight="fill"/>}</div>)}</section></div><div className="rule-presets" role="group" aria-label={t('命名ルールの例','Naming presets')}>{[['{date}_{title}','日付→件名','Date → title'],['{title}_{date}','件名→日付','Title → date']].map(([value,ja,en])=><button key={value} aria-pressed={rule===value} onClick={()=>{clearTimeout(timer.current);setRule(value);setRan(false);setBusy(false);}}>{t(ja,en)}</button>)}</div><form className="rule-form" onSubmit={e=>{e.preventDefault();if(valid)run();}}><label htmlFor="rule">{t('命名ルール','Naming rule')}</label><input id="rule" maxLength={70} value={rule} onChange={e=>{clearTimeout(timer.current);setBusy(false);setRule(e.target.value);setRan(false);}} aria-describedby="rule-help"/><button className="primary" disabled={!valid||busy}>{busy?t('処理中…','Processing…'):t('サンプルで実行','Run sample')}<Arrow/></button></form><p id="rule-help" className={valid?'support-note':'error-text'}>{valid?t('{date}＝日付、{title}＝件名。順番や区切り文字を自由に変更できます。','{date} = date, {title} = title. Change the order or add separators.'):t('{date} または {title} を含めてください。ファイル名に使えない記号は利用できません。','Include {date} or {title} and use valid filename characters.')}</p><div className="demo-bottom"><span><LockKey size={17}/>{t('サンプルのみ使用・ファイル送信なし','Sample data only. No files uploaded.')}</span>{ran&&<button className="text-link" onClick={download}><DownloadSimple size={18}/>{t('結果をCSVで保存','Download CSV')}</button>}<button className="text-link" onClick={()=>{clearTimeout(timer.current);setRule('{date}_{title}');setRan(false);setBusy(false);}}><ArrowCounterClockwise size={17}/>{t('リセット','Reset')}</button></div><p className="support-note">{t('このデモは命名ルールの体験用です。PDFの解析・ファイルの変更は行いません。','This demo simulates naming rules. It does not parse or modify PDF files.')}</p></div>;
}

function FlowDemo({lang}){
 const t=useCopy(lang);const [step,setStep]=useInteraction('flow.step',0),[date,setDate]=useInteraction('flow.date','2026-10-20'),[purpose,setPurpose]=useInteraction('flow.purpose','tour'),[people,setPeople]=useInteraction('flow.people',3);
 const resetFlow=()=>{setStep(0);setDate('2026-10-20');setPurpose('tour');setPeople(3);};
 return <div><div className="demo-intro"><p>{t('架空の見学予約を入力して、受付までの流れを試せます。','Try a fictional visit request, from entering details to confirmation.')}</p></div><ol className="flow-steps">{[['入力','Details'],['確認','Review'],['受付完了','Received']].map((s,n)=><li key={n} className={step>=n?'current':''} aria-current={step===n?'step':undefined}><span>{step>n?<CheckCircle size={20}/>:n+1}</span>{s[translations[lang]]}</li>)}</ol>{step===0?<form className="booking-form" onSubmit={e=>{e.preventDefault();setStep(1);}}><label>{t('見学希望日','Preferred date')}<input required type="date" min="2026-10-15" max="2027-03-31" value={date} onChange={e=>setDate(e.target.value)}/></label><label>{t('目的','Purpose')}<select value={purpose} onChange={e=>setPurpose(e.target.value)}><option value="tour">{t('施設見学','Campus tour')}</option><option value="meeting">{t('相談・面談','Consultation')}</option></select></label><label>{t('参加人数','Number of visitors')}<input required type="number" min={1} max={30} value={people} onChange={e=>setPeople(e.target.value)}/></label><div className="form-note"><LockKey size={20}/><p>{t('氏名や連絡先は不要です。実際の予約は送信されません。','No name or contact details needed. This will not create a real booking.')}</p></div><button className="primary">{t('入力内容を確認','Review details')}<Arrow/></button></form>:step===1?<div className="booking-review"><h4>{t('この内容で受付を試します','Review your sample request')}</h4><dl><div><dt>{t('見学希望日','Preferred date')}</dt><dd>{date}</dd></div><div><dt>{t('目的','Purpose')}</dt><dd>{purpose==='tour'?t('施設見学','Campus tour'):t('相談・面談','Consultation')}</dd></div><div><dt>{t('参加人数','Visitors')}</dt><dd>{people}{t('名',' people')}</dd></div></dl><div className="case-actions"><button className="text-link" onClick={()=>setStep(0)}><ArrowLeft size={18}/>{t('修正する','Edit')}</button><button className="primary" onClick={()=>setStep(2)}>{t('デモ受付を完了する','Complete sample request')}<Arrow/></button></div></div>:<div className="booking-success" aria-live="polite"><CheckCircle size={55} weight="light"/><h3>{t('デモの受付が完了しました。','Your sample request is complete.')}</h3><p>{t('受付番号 DEMO-001。実際の予約・通知は送信していません。','Reference DEMO-001. No real booking or notification was sent.')}</p><button className="primary" onClick={resetFlow}>{t('もう一度試す','Try again')}<ArrowCounterClockwise size={18}/></button></div>}{step<2&&<div className="demo-bottom"><button className="text-link" onClick={resetFlow}><ArrowCounterClockwise size={17} aria-hidden="true"/>{t('リセット','Reset')}</button></div>}</div>;
}

function Technology({project,lang}){
 const {content}=useContent();const t=useCopy(lang),p=Object.fromEntries(projectEntries(content.site))[project];
 const steps={atlas:['Sample JSON','Separate search & selection','Comparison table'],form:['Sample records','Rule validation','Preview → CSV'],flow:['Sample details','Review state','Demo confirmation']};
 const icons=project==='nest'?[FolderPlus,Folders,MagnifyingGlass,Swap]:[Stack,ListChecks,CheckCircle];
 return <section className="technology-section"><h2 className="section-icon-title"><Code size={22} aria-hidden="true"/>{t('動く仕組み','How it works')}</h2><ol className="mechanism-flow">{p.flow.map((s,n)=>{const Icon=icons[n%icons.length],label=s.includes(' / ')?localized(s.split(' / ').slice(0,2),lang):lang==='en'?(steps[project]?.[n]||s):s;return <li key={`${n}-${s}`}><span className="mechanism-number">{String(n+1).padStart(2,'0')}</span><Icon size={26} weight="light" aria-hidden="true"/><span>{label}</span>{n<p.flow.length-1&&<Arrow className="mechanism-arrow"/>}</li>;})}</ol><p className="support-note technology-stack"><Code size={17} aria-hidden="true"/>{p.tech.map(v=>v.includes(' / ')?v.split(' / ')[translations[lang]]:v).join(' · ')}</p>{PROJECT_IDS.includes(project)&&<p className="support-note">{t('ブラウザー内のサンプル処理です。AI推論・ファイル変更・実予約は行いません。','Browser-only sample processing. No live AI, file changes, or real bookings.')}</p>}</section>;
}
function Comments({project,lang,comments,onAdd}){
 const t=useCopy(lang);const [draft,setDraft]=useState(''),[reply,setReply]=useState(null),[notice,setNotice]=useState(''),[showOriginal,setShowOriginal]=useState(false);const field=useRef();
 const samples={atlas:['比較項目を自分で選べると、進路の検討に便利そうです。','It would be useful to choose the comparison criteria when exploring study options.'],form:['命名ルールを自分の業務に合わせて変えられますか？','Can I adapt the naming rule to my own workflow?'],flow:['確認画面から入力に戻れるのが、安心ですね。','Being able to go back from review makes this reassuring to use.']};
 useEffect(()=>setShowOriginal(false),[lang]);const post=e=>{e.preventDefault();if(!draft.trim())return;onAdd({id:Date.now(),body:draft.trim(),replyTo:!!reply});setDraft('');setReply(null);setNotice(t('この画面に追加しました。外部には公開されません。','Added to this screen. Nothing was published externally.'));};
 return <div><p className="comment-demo-note"><LockKey size={18}/>{t('コメントの体験版です。入力内容は再読み込みで消え、外部へ送信されません。','Comment demo: entries disappear on reload and are not sent anywhere.')}</p><article className="comment"><div className="avatar">S</div><div><strong>{t('サンプルコメント','Sample comment')}</strong><small>2026.10.14</small><p>{samples[project][showOriginal?1-translations[lang]:translations[lang]]}</p><div className="comment-actions"><button onClick={()=>{setReply('sample');field.current?.focus();}}>{t('返信','Reply')}</button><button onClick={()=>setShowOriginal(v=>!v)}>{showOriginal?t('元に戻す','Show translation'):t('英語で見る','View Japanese')}</button></div></div></article>{comments.map(c=><article className={`comment ${c.replyTo?'reply':''}`} key={c.id}><div className="avatar yours">Y</div><div><strong>{t('あなた（この画面のみ）','You (this screen only)')}</strong>{c.replyTo&&<small>{t('サンプルコメントへの返信','Reply to sample comment')}</small>}<p>{c.body}</p></div></article>)}<form className="comment-form" onSubmit={post}>{reply&&<div className="reply-note">{t('サンプルコメントに返信','Replying to the sample comment')}<button type="button" aria-label={t('返信を取り消す','Cancel reply')} onClick={()=>setReply(null)}><X size={18}/></button></div>}<label htmlFor="comment-input">{t('コメントを書く','Write a comment')}</label><textarea ref={field} id="comment-input" value={draft} maxLength={500} rows={3} onChange={e=>setDraft(e.target.value)} placeholder={t('質問や気づきを書く…','Share a question or an idea…')}/><div><small>{draft.length} / 500</small><button className="primary" disabled={!draft.trim()}>{t('この画面に追加','Add to this screen')}<Arrow/></button></div></form><p role="status" className="support-note">{notice}</p></div>;
}

function ArticleDetail({article:metadata,lang,setModal,projects,returnTo,rememberArticle,onTag}){
 const {content}=useContent(),{article,loading,error}=useArticle(metadata),t=useCopy(lang),display=article||metadata,project=projects[display?.project],hasDownload=!!projectDownload(project);
 const body=article?articleCopy(article,'body',lang):'',headings=articleHeadings(body),showContents=body.length>=1500&&headings.length>=3,related=display?relatedArticles(display,content.articles):[];
 return <article className="article-detail">{display?<><p className="article-meta"><NotePencil size={16} aria-hidden="true"/>{project?`${project.name} / `:''}{t('制作ノート','BUILD NOTE')}<span>·</span><span className="article-date"><CalendarBlank size={15} aria-hidden="true"/><time dateTime={display.date}>{display.date}</time></span>{display.updatedAt&&display.updatedAt!==display.date&&<span className="article-updated">{t('更新 ','Updated ')}<time dateTime={display.updatedAt}>{display.updatedAt}</time></span>}</p><h1 className="editorial-title" id="dialog-title" tabIndex={-1}>{articleCopy(display,'title',lang)}</h1><TagList tags={display.tags} lang={lang} onSelect={onTag}/><p className="editorial-lead">{articleCopy(display,'summary',lang)}</p>{loading&&<p role="status" className="support-note">{t('記事を読み込んでいます…','Loading article…')}</p>}{error&&<div className="article-load-error" role="alert"><p>{t('本文を読み込めませんでした。通信状態をご確認ください。','The article could not load. Check your connection.')}</p><button className="text-link" onClick={()=>window.location.reload()}>{t('再読み込み','Reload')}<ArrowCounterClockwise size={17}/></button></div>}{article&&<><ArticleImages images={article.images} lang={lang}/>{showContents&&<nav className="article-contents" aria-label={t('目次','On this page')}><p><ListChecks size={19} aria-hidden="true"/>{t('この記事の内容','On this page')}</p><ol>{headings.map(h=><li key={h.id}><a href={`#${h.id}`}>{h.text}</a></li>)}</ol></nav>}<ArticleBody text={body} headingIcons={article.project==='nest'?[Folders,LinkSimple,Stack,Palette]:[Compass,Stack,Code,CheckCircle]}/></>}{hasDownload&&<DownloadPanel project={project} lang={lang}/>}<div className="article-next"><div>{project&&<button className={hasDownload?'text-link':'primary'} onClick={()=>{rememberArticle();setModal({type:'project',project:display.project,tab:PROJECT_IDS.includes(display.project)?'demo':'overview',from:display.id});}}><BookOpen size={19} aria-hidden="true"/>{PROJECT_IDS.includes(display.project)?t('この作品を試す','Try this project'):t(`${project.name}の概要を見る`,`View ${project.name} overview`)}<Arrow diagonal/></button>}</div><ShareLink route={{type:'article',id:display.id}} lang={lang}/></div>{related.length>0&&<section className="article-related"><h2 className="section-icon-title"><NotePencil size={22} aria-hidden="true"/>{t('あわせて読む','Related notes')}</h2><NoteRows articles={related} lang={lang} projects={projects} setModal={setModal} headingLevel="h3"/></section>}<button className="text-link article-back" onClick={()=>setModal(returnTo?{type:'journal',...returnTo.params,restoreScroll:returnTo.scroll,focusArticle:returnTo.articleId}:{type:'journal'})}><ArrowLeft size={18} aria-hidden="true"/>{returnTo?t('検索結果へ戻る','Back to results'):t('制作ノート一覧へ','All build notes')}</button></>:<h1 id="dialog-title" tabIndex={-1}>{t('この記事は公開されていません。','This article is not published.')}</h1>}</article>;
}

function ShareLink({route,lang}){
 const t=useCopy(lang),[status,setStatus]=useState(''),[fallback,setFallback]=useState('');
 useEffect(()=>{setStatus('');setFallback('');},[routeHash(route),lang]);
 const share=async()=>{const url=window.location.origin+routeHash(route);try{await navigator.clipboard.writeText(url);setStatus(t('URLをコピーしました','Link copied'));setFallback('');}catch{setFallback(url);setStatus(t('下のURLを選択してコピーしてください','Select and copy the link below'));}};
 return <div className="share-control"><button className="text-link" onClick={share}><LinkSimple size={18} aria-hidden="true"/>{t('リンクをコピー','Copy link')}</button><span role="status">{status}</span>{fallback&&<input readOnly value={fallback} onFocus={e=>e.target.select()} aria-label={t('共有URL','Share URL')}/>}</div>;
}

function CommunitySection({project,lang,initialOpen,comments,onAdd}){
 const t=useCopy(lang),[expanded,setExpanded]=useState(initialOpen);
 useEffect(()=>setExpanded(initialOpen),[initialOpen,project]);
 return <details className="community-disclosure" open={expanded} onToggle={e=>setExpanded(e.currentTarget.open)}><summary><ChatCircle size={18} aria-hidden="true"/>{publicCommentsEnabled?t('コメント','Comments'):t('コメントを試す','Try comments')}<small>{publicCommentsEnabled?'GitHub':t('この画面のみ','On this screen only')}</small></summary>{expanded&&<Community project={project} lang={lang}><Comments project={project} lang={lang} comments={comments} onAdd={onAdd}/></Community>}</details>;
}
